def force_reconnect_when_fhnet_connection_failure(func):
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        try:
            func(self, *args, **kwargs)

        except ConnectFailedError:
            log_exception("ConnectFailedError exception occurred, building new connection to FHNET container")
            self.force_reconnect(connection=self.get_fhnet_alias())
            func(self, *args, **kwargs)

    return wrapper


class Smod(Device):

    def __init__(self):
        super(Smod, self).__init__()
        self._fhnet_container_ip = '192.168.255.254'
        self._fhnet_alias = 'FHNET'
        self._admin = admin()
        self._ssh_connection_instance = None

    @log_input_and_output
    def get_fhnet_alias(self):
        return self._fhnet_alias

    @log_input_and_output
    def connect_to(self, address, username, password, proxy=None, alias=None):
        """
        Connects to system module via ssh and admin.

        :param address: Address to system module
        :type address: str
        :param username: Username that should be used in authentication.
        :type username: str
        :param password: Password that will be used in authentication and to try to decrypt the
            private key if needed.
        :type password: str
        :param proxy: Opened connection to the remote host, from which the new
            connection will be started.
        :type proxy: Connection, optional
        :param alias: Name of device; if None provided then default alias will be used
        :type alias: str or None
        """
        self._ssh_connection_instance = self._connect_to(
            hostname=address, username=username, password=password, proxy=proxy, alias=alias
        )

    @log_input_and_output
    def connect_to_container_via_smod(
        self, container_ip, username, password, container_alias, timeout=None
    ):
        """
        Connects to particular container via system module.

        WARNING! This will not work on devices which are not supporting FHNET container connections.

        :param container_ip: ip address to particular container
        :type container_ip: str
        :param username: Username that should be used in authentication.
        :type username: str
        :param password: Password that will be used in authentication and to try to decrypt the
            private key if needed.
        :type password: str
        :param container_alias: alias for container connection
        :type container_alias: str
        :param timeout: (optional) Timeout for keyword execution, None by
            default. Accepts a timeout string in Robot Framework format.
            If None, waits for the command to end indefinitely.
        :type timeout: str or int
        """
        log_operation("Connecting to container: {} via system module via ssh".format(container_ip))

        self._connect_to(
            hostname=container_ip,
            username=username,
            password=password,
            alias=container_alias,
            proxy=self.get_alias(),
            timeout=timeout,
        )

        log_result("Connected to container: {}".format(container_ip))

    @log_input_and_output
    @force_reconnect_when_fhnet_connection_failure
    def connect_to_fhnet_container(self, username, password, timeout=5):
        """
        Connects to fhnet container on device unit (0x1018 or 0x2018 lx container).

        WARNING! This will not work on devices which are not supporting FHNET container connections.

        :param username: Username that should be used in authentication.
        :type username: str
        :param password: Password that will be used in authentication and to try to decrypt the
            private key if needed.
        :type password: str
        :param timeout: Timeout for particular keyword execution, 5 seconds on default.
                        Accepts a timeout string in Robot Framework format.
        :type timeout: int/str
        """
        container = self._get_fhnet_container_name()

        self._start_ssh_server_with_fhnet_container(container)

        self.connect_to_container_via_smod(
            container_ip=self._fhnet_container_ip,
            container_alias=self._fhnet_alias,
            username=username,
            password=password,
            timeout=timeout,
        )

    @log_input_and_output
    def close_connection_to_fhnet_container(self):
        """
        Closes connection to FHNET container.

        WARNING! This will not work on devices which are not supporting FHNET container connections.
        """
        fhnet_alias = self.get_fhnet_alias()

        log_operation("Closing connection to FHNET container.")

        self.close_inner_connection(
            inner_alias=fhnet_alias
        )

        log_result("Connection to {0} closed.".format(fhnet_alias))

    @log_input_and_output
    def get_rus_ips(self, timeout=15):
        """
        Gets radios units ip addresses via Admin Connection.

        :param timeout: Timeout for particular keyword execution, 5 seconds on default.
                        Accepts a timeout string in Robot Framework format.
        :type timeout: int/str
        :return: radio unit ip addresses found in container
        :rtype: list of strings
        """
        return [ru['parameters']['ipAddress'] for ru in self._get_rus_data(timeout=timeout)]

    @log_input_and_output
    def get_rus_ips_and_serial_numbers(self, timeout=15):
        """
        Gets radio unit ip addresses together with appropriate serial numbers via Admin Connection.

        :param timeout: Timeout for particular keyword execution, 5 seconds on default.
                        Accepts a timeout string in Robot Framework format.
        :type timeout: int/str
        :return: radio unit ip addresses and serial numbers found in container,
                 i.e [('172.16.77.129', '1M211806825'), ('172.22.56.2', '1M204964030')]
                     or
                     [('10.202.11.130', 'L1232908042'), ('10.202.11.131', 'L1234903428')]
        :rtype: list(tuple(str))
        """
        return [(ru['parameters']['ipAddress'], ru['parameters']['serialNumber'])
                for ru in self._get_rus_data(timeout=timeout)]

    @log_input_and_output
    def get_rus_ips_and_ru_type(self, timeout=15):
        """
        Gets radio units ip addresses together with appropriate radio type via Admin Connection.

        :param timeout: Timeout for particular keyword execution, 5 seconds on default.
                        Accepts a timeout string in Robot Framework format.
        :type timeout: int/str
        :return: radio unit ip addresses and radio type found in container,
                 i.e [('172.16.77.129', 'AEQN'), ('172.22.56.2', 'AEQN')]
        :rtype: list(tuple(str))
        """
        return [(ru['parameters']['ipAddress'], ru['parameters']['productName'])
                for ru in self._get_rus_data(timeout=timeout)]

    @log_input_and_output
    def get_rfsw_from_targetbd(self, radio_type, radio_protocol_type):
        """
        Gets Radio software from TargetBD

        :param radio_type: Radio type taken from testline configuration file
                        e.g ${tl.gnbs[0].dus[0].rus[%s].radio_type}
        :type radio_type: str
        :return: Radio Sw eg. 'FRM59.10.R16L', empty string if can't be get
        :param radio_protocol_type: radio protocol type, e.g. 'eCPRI'
        :type radio_protocol_type: str
        :rtype str
        """
        params = self._get_params_from_targetbd_file(
            "{}{}".format(radio_type, "_C1" if radio_type == "AAFB" or radio_type == "AAIB" else ""),
            radio_protocol_type
        )

        for param in params.split(" "):
            if "resourceSWVersion" in param:
                try:
                    return param.split('"')[1]
                except IndexError:
                    raise TargetBdError(
                        "Content of /ffs/run/TargetBD*.xml has changed and parser need to aligned!"
                    )
        return ""

    @log_input_and_output
    def get_enb_rfsw_from_targetbd(self, radio_type):
        """
        Gets eNB Radio software from TargetBD

        :param radio_type: Radio type taken from testline configuration file
                        e.g ${tl.enbs[0].rms[%s].radio_type}
        :type radio_type: str
        :return: Radio Sw eg. 'FRM59.10.R16L', empty string if can't be get
        :rtype str
        """
        params = self._get_enb_params_from_targetbd_file(radio_type)

        for param in params.split(" "):
            if "resourceSWVersion" in param:
                try:
                    return param.split('"')[1]
                except IndexError:
                    raise TargetBdError(
                        "Content of /ffs/run/TargetBD*.xml has changed and parser need to aligned!"
                    )
        return ""

    @log_input_and_output
    def get_enb_rfsw_from_targetbd_with_radio_type(self, radio_type):
        """
        Gets all matching eNB Radio sw versions from TargetBD. Method can return more than one Radio sw
        version, since there can be multiple versions of provided radio type in TargetBD eg. 'FRGP' and 'FRGP_N1'.

        :param radio_type: Radio type e.g. "FRGU", can be taken from testline configuration file
        ${tl.enbs[0].rms[%s].radio_type} or via admin
        :type radio_type: str
        :return: Radio Sw with radio type eg.
        {
            'radio_type': 'FRGP'
            'sw_versions': ['FRM59.10.R16L']
        }
        ,empty list for 'sw_versions' if sw can't be get
        :rtype dict
        :raise TargetBDError: When TargetBD has wrong content.
        """
        ru_sw = {"radio_type": radio_type, "sw_versions": []}

        params = self._get_enb_params_from_targetbd_file(radio_type)

        for param in params.split(" "):
            if "resourceSWVersion" in param:
                try:
                    ru_sw["sw_versions"].append(param.split('"')[1])
                except IndexError:
                    raise TargetBdError(
                        "Content of /ffs/run/TargetBD*.xml has changed and parser need to aligned!"
                    )
        return ru_sw

    @log_input_and_output
    def get_loner_version(self):
        """
        Gets loner fw version using output from: chk sysversion.

        :return: Extracted loaner version eg.'LONER-FDD-CPRI_5G20B.0.0.20201205-120547', empty string if not found
        :rtype str
        """
        return self._get_component_version("loner")

    @log_input_and_output
    def get_sw_version_from_targetbd(self, convert=True):
        """
        Gets software version from active partition

        :param convert: If True, convert head of latest trunk to SBTS00 (ex. SBTS22R3 -> SBTS00). True at default.
        :type convert: bool
        :return: Software version on active partition
                 E.g. output: '5G19A_FSMK_0006_038451_000299'
        :rtype: str
        """
        sw_package = self.get_sw_version_as_list_from_targetbd()

        if sw_package is not None:
            try:
                active_sw_package = self._get_active_sw_package(sw_package, convert)
                log_step("Active Sw package: {}".format(active_sw_package))

                if "0.800." in active_sw_package:
                    active_sw_package = "5G_{}".format("".join(active_sw_package.split("_")[1]))

                if "T1" in active_sw_package or "T2" in active_sw_package:
                    return active_sw_package[:-2]

            except IndexError:
                raise TargetBdError(
                    "TargetBD has wrong content. TargetBD: {}".format(sw_package)
                )

        else:
            active_sw_package = sw_package

        return active_sw_package

    @log_input_and_output
    def get_sw_version_as_list_from_targetbd(self):
        """
        Gets software stream version from TargetBD and split it into list.

        :return: Software name in list. eg. ['5G21A', 'GNB', '', '800' ,'3253']
        :rtype: List[str]
        :raise TargetBDError: When TargetBD has wrong content.
        """
        try:
            target_bd = self.execute(command="ls /ffs/run | grep TargetBD_SBTS").split("\r\n")
            log_step("Read TargetBD: {}".format(target_bd))

            sw_version = target_bd[0].lstrip("TargetBD_").rstrip(".xml")
            log_step("Read sw_version: {}".format(sw_version))

        except AttributeError:
            raise TargetBdError(
                "Reading TargetBD failed, command seems outdated."
            )

        return [i.lstrip("0") for i in sw_version.split("_")]

    @log_input_and_output
    def check_gps(self):
        """
        Checks GPS status and verifies if it is correct for plugged in receiver.

        :return: True if status is correct (`0x1`), False otherwise
        :rtype: bool
        """
        log_operation("Reading GPS status.")

        self.send_command(command='cat /sys/class/clk/clk-fpga/regs/clk_status_pps_ref_ro')

        gps_status = self.read_output()

        log_result("Read GPS status: {}".format(gps_status))

        return gps_status == '0x1'

    @log_input_and_output
    def start_tcpdump(self, file_path='/tmp/log.pcap', specific_cmd=None):
        """
        Starts tcpdump collection on system module to fully provided path (/tmp/log.pcap at default).
        :param file_path Full path on system module where pcap should be collected.
        :type file_path: str
        :param specific_cmd param to customize of default tcpdump command, add flags, etc.
        :type specific_cmd: str

        :return: process ID of started tcp dump collection
        :rtype: str
        """
        if specific_cmd:
            self.send_command("{0} -w '{1}'> /dev/null 2>&1 & echo $!".format(specific_cmd, file_path))
        else:
            self.send_command("tcpdump -U -i any sctp -w '{0}' > /dev/null 2>&1 & echo $!".format(file_path))
        pid = self.execute("ps aux | grep [t]cpdump | grep {}".format(file_path)).split()[1]
        return pid

    @log_input_and_output
    def stop_tcpdump_by_pid(self, pid):
        """ Stops selected tcpdump process on system module. """
        self.send_command("kill -15 {0}".format(pid))

    @log_input_and_output
    def stop_tcpdump(self):
        """ Stops all tcpdump processes on system module. """
        self.send_command('killall -9 tcpdump')

    @log_input_and_output
    def clear_blackbox(self):
        """
        Clears already collected blackbox logs under `/ffs/run/config/lifedata/blackbox` and `/ffs/run/logs/blackbox`
        paths.
        """
        self.send_command('echo > /ffs/run/config/lifedata/blackbox')
        self.send_command('echo > /ffs/run/logs/blackbox')

    @log_input_and_output  # noqa: C901
    def get_bbmods_topology_info(self, get_other_cpus_info=False, slave_bts=False):
        """
        Returns a list of dictionaries with information about bbmods link to current smod based on the output
        of "chk topo" command. Dictionaries have basic information required to create ssh connection to bbmods.
        :param get_other_cpus_info: True if topology info from all baseband module cpus should be collected,
                                    False if collected from main cpu only. Defaults to False.
        :type get_other_cpus_info: bool
        :param slave_bts: Used for fullrack configuration only. True if command should be performed on the slave BTS,
                          False otherwise. Defaults to False
        :type slave_bts: bool

        :return: list of dictionaries with bbmods info
                 e.g. [{'username': 'toor4nsn', 'password': 'oZPS0POrRieRtu', 'alias': 'B2_ABIP', 'slot': 'slave B2',
                 'hw_name': 'ABIP', 'address': 'fsp2s0icom', 'node_id': '0x1330','login_shortcut': 'bsh 2:0'}]
        :rtype: list of dict
        :raises UnknownCommandContent: if content of chk topo is not recognized (content of the command might
                have changed)
        """
        bbmods_attributes = self._get_bbmods_attributes(slave_bts=slave_bts)
        bbmods_info = []

        for bbmod in bbmods_attributes:
            address, node_id = self._get_bbmod_address_and_node_id(bbmod)
            alias, slot, hw_name = self._get_bbmod_alias_slot_and_hw_name(bbmod)

            bbmod_info = {'username': 'toor4nsn',
                          'password': 'oZPS0POrRieRtu',
                          'alias': alias,
                          'slot': slot,
                          'hw_name': hw_name,
                          'address': address,
                          'node_id': node_id,
                          'login_shortcut': 'bsh ' + self._convert_bbmod_node_id_to_bsh_number(node_id)}

            bbmods_info.append(bbmod_info)

        return bbmods_info if get_other_cpus_info else self._remove_other_cpus_info(bbmods_info)

    def _get_bbmod_address_and_node_id(self, bbmod):
        """
        Gets address and node ID from list of bbmod attributes.
        :param bbmod: list of bbmod attributes
        :type bbmod: list of str

        :return: address and node ID of particular bbmod
        :rtype: tuple(str)
        :raises UnknownCommandContent: if content of chk topo is not recognized (content of the command might
                have changed)
        """
        address = ''
        node_id = ''
        for attribute in bbmod:
            if '(' in attribute and ')' in attribute:
                address = attribute[1:-1]
            if '[' in attribute and ']' in attribute:
                node_id_search = re.search(r"0x[1-2][2-4][3-6]0|0x[1-2]0[3-5]1", attribute)
                if node_id_search:
                    node_id = node_id_search.group()
                else:
                    raise UnknownCommandContent("Content of chk topo contains unsupported node ID format and parser needs to be aligned!")

        if address == '' or node_id == '':
            raise UnknownCommandContent("Content of chk topo has changed and parser needs to be aligned!")

        return address, node_id

    def _get_bbmod_alias_slot_and_hw_name(self, bbmod):
        """
        Gets alias, slot and hw name from list of bbmod attributes.
        :param bbmod: list of bbmod attributes
        :type bbmod: list of str

        :return: alias, slot and hw name of particular bbmod
        :rtype: tuple(str)
        :raises UnknownCommandContent: if content of chk topo is not recognized (content of the command might
                have changed)
        """
        try:
            alias = bbmod[2] + '_' + bbmod[3]
            slot = bbmod[1] + ' ' + bbmod[2]
            hw_name = bbmod[3]
        except IndexError:
            raise UnknownCommandContent("Content of chk topo has changed and parser needs to be aligned!")

        alias_match = re.fullmatch(r"(B|C)\d_[A-Z]+", alias)
        slot_match = re.fullmatch(r"slave\s(B|C)\d", slot)
        hw_name_match = re.fullmatch(r"[A-Z]+", hw_name)

        if not alias_match or not slot_match or not hw_name_match:
            raise UnknownCommandContent("Content of chk topo has changed and parser needs to be aligned!")

        return alias, slot, hw_name

    def _convert_bbmod_node_id_to_bsh_number(self, node_id):
        """
        Converts bbmod's node ID to bsh number.

        For ASOx mosules:
            0x1051 -> 0:1,    0x2051 -> 0:1
            0x1031 -> 0:2,    0x2031 -> 0:2
            0x1041 -> 0:3,    0x2041 -> 0:3

        For classical baseband units:
            0x1230 -> 1:0,    0x2230 -> 1:0
            0x1240 -> 1:1,    0x2240 -> 1:1
            0x1250 -> 1:2,    0x2250 -> 1:2
            0x1260 -> 1:3,    0x2260 -> 1:3

            0x1330 -> 2:0,    0x2330 -> 2:0
            0x1340 -> 2:1,    0x2340 -> 2:1
            0x1350 -> 2:2,    0x2350 -> 2:2
            0x1360 -> 2:3,    0x2360 -> 2:3

            0x1430 -> 3:0,    0x2430 -> 3:0
            0x1440 -> 3:1,    0x2440 -> 3:1
            0x1450 -> 3:2,    0x2450 -> 3:2
            0x1460 -> 3:3,    0x2460 -> 3:3

        :param node_id: bbmod's node ID to convert e.g. '0x1230'
        :type node_id: str
        :return: converted bsh login shortcut e.g. '1:1'
        :rtype: str
        """
        node_id_to_bsh_id = {'0x1051': '0:1', '0x1031': '0:2', '0x1041': '0:3',
                            '0x2051': '0:1', '0x2031': '0:2', '0x2041': '0:3',
                            '0x1230': '1:0', '0x1240': '1:1', '0x1250': '1:2', '0x1260': '1:3',
                            '0x2230': '1:0', '0x2240': '1:1', '0x2250': '1:2', '0x2260': '1:3',
                            '0x1330': '2:0', '0x1340': '2:1', '0x1350': '2:2', '0x1360': '2:3',
                            '0x2330': '2:0', '0x2340': '2:1', '0x2350': '2:2', '0x2360': '2:3',
                            '0x1430': '3:0', '0x1440': '3:1', '0x1450': '3:2', '0x1460': '3:3',
                            '0x2430': '3:0', '0x2440': '3:1', '0x2450': '3:2', '0x2460': '3:3'}

        if node_id_to_bsh_id.get(node_id):
            return node_id_to_bsh_id[node_id]

        raise NodeIDNotSupported(f"Provided node ID: '{node_id}' cannot be matched with bsh number.")

    def _remove_other_cpus_info(self, bbmods_info):
        """
        Removes other cpus info from list of dictionaries with information about bbmods info.

        :param bbmods_info: list of dictionaries with information about bbmods info
        :type bbmods_info: list of dict
        :return: list of dictionaries with information about bbmods info without other cpus info
        :rtype: list of dict
        """
        return [bbmod_info for bbmod_info in bbmods_info if ":0" in bbmod_info['login_shortcut']]

    @log_input_and_output
    def get_smod_time(self):
        """
        Gets current time on system module.

        :return: Current time on system module
        :rtype: datetime object
        """
        time_str = self.execute(command="date")
        dt = parser.parse(time_str).replace(tzinfo=None)
        return dt

    @log_input_and_output
    def _get_component_version(self, sw_component_name):
        """
        Gets specified software/firmware component version using output from: chk sysversion
        Example:   B1 loner = LONER-FDD-CPRI_5G20B.0.0.20201205-123457 ...........

        :param sw_component_name: name of particular software/firmware component eg. 'loner'
        :type sw_component_name: str
        :return: Extracted sw component version eg.'LONER-FDD-CPRI_5G20B.0.0.20201205-120547',empty string if not found
        :rtype str
        """
        params = str(self.execute(command="chk sysversion")).split("\r")

        for line in params:
            if sw_component_name in line:
                try:
                    return line.split("=")[1].split(" ..")[0].strip()

                except IndexError:
                    raise UnknownCommandContent(
                        "Content of chk version has changed and parser needs to be aligned!"
                    )

        return ""

    @log_input_and_output
    def _start_ssh_server_with_fhnet_container(self, container):
        """
        Initializes ssh server with fhnet container resources to get possibility to connect via
        standard ip address of container via ssh.

        :param container: name of particular container on device unit
        :type container: str
        """
        con = self.get_connection_by_alias(self.get_alias())

        try:
            con.execute(
                'lxc-attach -n {0} -- /usr/sbin/sshd -p 22 -f /dev/null -o "PermitRootLogin yes"'.format(
                    container
                )
            )

        except SSHException as ex:
            log_exception("Error during initializing ssh server on FHNET container")
            raise ex

    @log_input_and_output
    def _get_containers(self, timeout=5):
        """
        Gets containers list from device unit via SSH connection.

        :param timeout: Timeout for keyword execution, 5 seconds on default.
                        Accepts a timeout string in Robot Framework format.
        :type timeout: int/str
        :return: Containers list read from device unit.
        :rtype: str
        """
        log_step("Getting containers")
        containers = self.execute(command="lxc-ls", timeout=timeout)

        log_step("Read containers list: {0}".format(containers))
        return containers

    @log_input_and_output
    def _get_fhnet_container_name(self):
        """
        Gets FHNET container name on device unit with 5GC001834 feature enabled.
        Might be 0x1018 or 0x2018 (depends on BTS configuration),

        :return: FHNET container name
        :rtype: str
        :raises: ContainerIsNotPresent if neither of the containers mentioned above are present on device unit.
                 Might suggest that feature is not enabled on this device.
        """
        pattern = r"0x[12]018"

        containers = self._get_containers()
        log_step("Found containers: {}".format(containers))

        fhnet = re.findall(pattern, containers)
        log_step("Found FHNET containers: {}".format(fhnet))

        if not fhnet:
            raise ContainerIsNotPresent(
                "FHNET container is not present on system module!\n"
                "Read containers: {0}".format(containers)
            )

        return fhnet[0]

    @log_input_and_output
    def _get_rus_data(self, timeout):
        self._create_admin_session()
        try:
            return self._admin.get_managed_objects(class_name="RMOD_L", timeout=timeout, connection=self._alias)
        finally:
            self._admin.teardown(connection=self._alias)

    @log_input_and_output
    def _get_params_from_targetbd_file(self, radio_type, radio_protocol_type):
        ssh_cmd = (
            "cat /ffs/run/TargetBD*.xml | grep {} | grep resourceSWVersion".format(
                radio_type
            )
        )

        if radio_protocol_type == 'eCPRI':
            ecpri_ssh_cmd = (
                "cat /ffs/run/TargetBD*.xml | grep {}_E1 | grep resourceSWVersion".format(
                    radio_type
                )
            )
            params = str(self.execute(ecpri_ssh_cmd))

            if params:
                return params

        return str(self.execute(ssh_cmd))

    def _get_enb_params_from_targetbd_file(self, radio_type):
        ssh_cmd = (
            "cat /ffs/run/TargetBD*.xml | grep {} | grep resourceSWVersion".format(
                radio_type
            )
        )

        return str(self.execute(ssh_cmd))

    def _get_active_sw_package(self, sw_package, convert):
        if all(
                (
                    self._is_year_and_quarter_in_sw_package_name(sw_package),
                    sw_package[2] == ''
                )
        ):
            sw_package[2] = "0" * 4
            sw_package[3] = sw_package[3].rjust(6, "0")
            if "T" in sw_package[4]:
                sw_package[4] = sw_package[4].rjust(8, "0")
            else:
                sw_package[4] = sw_package[4].rjust(6, "0")
            active_sw_package = "_".join(sw_package)

        elif "SBTS" in sw_package[0]:
            if "T" in sw_package[4]:
                sw_package[4] = sw_package[4].rjust(8, "0")
            else:
                sw_package[4] = sw_package[4].rjust(6, "0")
            active_sw_package = "{}_{}".format(
                "SBTS00" if convert else sw_package[0], "_".join(sw_package[1:])
            )

        else:
            if sw_package[-3] == "":
                sw_package[-3] = "0"
            active_sw_package = sw_package[0] + "_" + ".".join(sw_package[-3:])

        return active_sw_package

    @staticmethod
    def _is_year_and_quarter_in_sw_package_name(sw_package):
        return any("SBTS{}R{}".format(year, quarter) in sw_package for year in range(22, 27) for quarter in range(1, 5))

    @log_input_and_output
    def _get_bbmods_attributes(self, slave_bts=False):
        """
        Returns a list of lists with bbmods attributes based on the output of "chk topo" command.
        Lists contain the attributes from line with 'slave B' or 'slave C' slot.
        :param slave_bts: Used for fullrack configuration only. True if command should be performed on the slave BTS,
                          False otherwise. Defaults to False
        :type slave_bts: bool

        :return: list of lists with bbmods attributes
        :rtype: list of list
        """
        bts_bbmods_topo = self._get_topology_info(slave_bts=slave_bts)
        bbmods = [entry for entry in bts_bbmods_topo if any(['slave B' in entry, 'slave C' in entry])]

        bbmods_attributes = []
        for bbmod in bbmods:
            bbmods_attributes.append([attribute for attribute in str(bbmod).split(' ') if attribute])
        return bbmods_attributes

    @log_input_and_output
    def _get_topology_info(self, slave_bts):
        """
        Returns a list of lines of output of "chk topo" command.
        All required authorizations are handled automatically using default smod credentials.
        :param slave_bts: Used for fullrack configuration only. True if command should be performed on the slave BTS,
                          False otherwise.
        :type slave_bts: bool

        :return: output of "chk topo" command split into lines
        :rtype: list of str
        :raises CommandError exception when "chk topo" command execution has failed.
        """
        smod_invoke_session = InvokeSshHandler()
        command_output = smod_invoke_session.get_chk_topo_output_from_smod(timeout=30, slave_bts=slave_bts)

        if re.search("error", command_output, re.IGNORECASE) is not None:
            raise CommandError(f"Command 'chk topo' execution ERROR found: {command_output}")
        elif not command_output:
            raise CommandError("Unknown command error, output is empty...")

        return command_output.split("\n")

    def _create_admin_session(self):
        proxy_credentials = {}
        proxy_obj = self._ssh_connection_instance.params.get("proxy")
        if proxy_obj:
            proxy_credentials["hostname"] = proxy_obj.params["hostname"]
            proxy_credentials["username"] = proxy_obj.params["username"]
            proxy_credentials["password"] = proxy_obj.params["password"]
            log_step("Creating admin session for connection with proxy.\n"
                     f"Proxy connection IP: {proxy_credentials['hostname']}.\n"
                     f"BTS connection IP: {self._ssh_connection_instance.params['hostname']}")
        else:
            proxy_credentials["hostname"] = proxy_credentials["username"] = proxy_credentials["password"] = None
            log_step("Creating admin session for connection without proxy. \n"
                     f"BTS connection IP: {self._ssh_connection_instance.params['hostname']}")

        try:
            self._admin.setup_admin(bts_host=self._ssh_connection_instance.params["hostname"],
                                    remote_host=proxy_credentials["hostname"],
                                    remote_host_username=proxy_credentials["username"],
                                    remote_host_password=proxy_credentials["password"],
                                    name=self._alias)
            log_result(f"Successfully connected with `{self._alias}` alias via admin!")
        except AliasInUse:
            log_result(f"Admin session with `{self._alias}` alias already exists, reusing existing session.")


